export const W=160,H=100;
export const colors=['#c3a66d','#819b84','#bd7e69','#889aaa','#a18aab','#b7b773','#78a5a2','#c598a3','#a69276','#8c9e68','#b48d59','#7e8fb2'];
const names=['Aurelian Empire','Kingdom of Veyr','Ashen Marches','Northreach','The Velorian Pact','Sundale','Isles of Thalen','Rosewater','Karth Dominion','Elderwood','Solmere','Frosthold'];
export function random(s){s.rng=(s.rng+0x6D2B79F5)|0;let t=s.rng;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return ((t^t>>>14)>>>0)/4294967296;}
export function neighbors(i){const x=i%W,y=Math.floor(i/W);return [x>0?i-1:-1,x<W-1?i+1:-1,y>0?i-W:-1,y<H-1?i+W:-1].filter(j=>j>=0);}
export function log(s,text,type='world'){s.events.unshift({year:s.year,text,type});s.events.length=Math.min(s.events.length,100);}
export function stats(s){const counts=Array(s.nations.length).fill(0);s.owner.forEach(n=>{if(n>=0)counts[n]++;});return counts;}
export function createWorld(seed='ELDER-1482',count=8){let hash=2166136261;for(const c of seed)hash=Math.imul(hash^c.charCodeAt(0),16777619);const s={version:1,seed,rng:hash,year:1,owner:Array(W*H).fill(-1),terrain:[],nations:[],wars:[],alliances:[],events:[]};const phase=Array.from({length:8},()=>random(s)*6.28);for(let y=0;y<H;y++)for(let x=0;x<W;x++){const nx=x/W,ny=y/H;const field=Math.sin(nx*10+phase[0])*.25+Math.cos(ny*12+phase[1])*.22+Math.sin(nx*19+ny*13+phase[2])*.13+Math.cos(nx*34-ny*23+phase[3])*.065+Math.sin(nx*65+ny*51)*.025;const edge=Math.min(nx,1-nx,ny,1-ny);s.terrain.push(field+Math.min(edge*3,.38)-.23);}
const land=s.terrain.map((v,i)=>v>0?i:-1).filter(i=>i>=0);const seeds=[];for(let n=0;n<count;n++){let best=land[Math.floor(random(s)*land.length)],distance=-1;for(let k=0;k<150;k++){const i=land[Math.floor(random(s)*land.length)];const d=seeds.length?Math.min(...seeds.map(j=>(i%W-j%W)**2+(Math.floor(i/W)-Math.floor(j/W))**2)):random(s);if(d>distance){distance=d;best=i;}}seeds.push(best);s.nations.push({id:n,name:names[n],color:colors[n],capital:best,wealth:80+Math.floor(random(s)*80),stability:80,population:20000,aggression:.3+random(s)*.6});}
for(const i of land){let best=0,d=Infinity;seeds.forEach((j,n)=>{const v=(i%W-j%W)**2+(Math.floor(i/W)-Math.floor(j/W))**2;if(v<d){d=v;best=n;}});s.owner[i]=best;}
const counts=stats(s);s.nations.forEach((n,i)=>n.population=counts[i]*320);log(s,'The age of kingdoms begins. Eight centuries lie unwritten.');return s;}
const pair=(a,b)=>[Math.min(a,b),Math.max(a,b)];
const has=(list,a,b)=>list.some(p=>p[0]===Math.min(a,b)&&p[1]===Math.max(a,b));
export function declareWar(s,a,b){if(a===b||has(s.wars,a,b)||!stats(s)[a]||!stats(s)[b])return false;s.alliances=s.alliances.filter(p=>!has([p],a,b));s.wars.push([...pair(a,b),s.year]);log(s,`${s.nations[a].name} declares war on ${s.nations[b].name}.`,'war');return true;}
export function peace(s,a){const ended=s.wars.filter(p=>p.includes(a,0)&& (p[0]===a||p[1]===a));s.wars=s.wars.filter(p=>p[0]!==a&&p[1]!==a);if(ended.length)log(s,`${s.nations[a].name} signs a peace accord.`,'peace');return ended.length;}
export function rebel(s,a){const cells=s.owner.map((n,i)=>n===a?i:-1).filter(i=>i>=0);if(cells.length<80||s.nations.length>=24)return false;const center=cells[Math.floor(random(s)*cells.length)],id=s.nations.length;const old=s.nations[a];const name=`Free ${old.name.replace(/^(Kingdom of |The |Isles of )/,'').split(' ')[0]}`;s.nations.push({id,name,color:colors[id%colors.length],capital:center,wealth:60,stability:70,population:1,aggression:.6});const sorted=cells.sort((i,j)=>((i%W-center%W)**2+(Math.floor(i/W)-Math.floor(center/W))**2)-((j%W-center%W)**2+(Math.floor(j/W)-Math.floor(center/W))**2));const taken=sorted.slice(0,Math.floor(cells.length*.25));taken.forEach(i=>s.owner[i]=id);s.nations[id].population=Math.floor(old.population*.25);old.population-=s.nations[id].population;old.stability=65;log(s,`${name} rises in rebellion against ${old.name}.`,'war');declareWar(s,id,a);return true;}
export function tick(s){s.year++;const counts=stats(s),borders=[];for(let i=0;i<s.owner.length;i++){const a=s.owner[i];if(a<0)continue;for(const j of [i%W<W-1?i+1:-1,i+W<s.owner.length?i+W:-1]){if(j>=0&&s.owner[j]>=0&&a!==s.owner[j])borders.push([i,j]);}}
const touching=[...new Set(borders.map(([i,j])=>pair(s.owner[i],s.owner[j]).join(',')))].map(p=>p.split(',').map(Number));for(const [a,b] of touching){if(!has(s.wars,a,b)&&!has(s.alliances,a,b)&&random(s)<.012*(s.nations[a].aggression+s.nations[b].aggression))declareWar(s,a,b);else if(!has(s.wars,a,b)&&!has(s.alliances,a,b)&&random(s)<.003){s.alliances.push(pair(a,b));log(s,`${s.nations[a].name} and ${s.nations[b].name} form an alliance.`,'peace');}}
for(let k=0;k<Math.min(180,borders.length);k++){const [i,j]=borders[Math.floor(random(s)*borders.length)],a=s.owner[i],b=s.owner[j];if(a===b||!has(s.wars,a,b))continue;const power=n=>Math.sqrt(counts[n]+1)*(s.nations[n].stability+40)*(s.nations[n].wealth+100);if(random(s)<power(a)/(power(a)+power(b)))s.owner[j]=a;else s.owner[i]=b;}
s.wars=s.wars.filter(([a,b,start])=>{if(s.year-start>8&&random(s)<.09){log(s,`${s.nations[a].name} and ${s.nations[b].name} agree to peace.`,'peace');return false;}return true;});const now=stats(s);s.nations.forEach((n,i)=>{if(!now[i]){if(counts[i])log(s,`${n.name} has fallen. Its lands pass into history.`,'war');n.population=0;return;}if(s.owner[n.capital]!==i)n.capital=s.owner.indexOf(i);const fighting=s.wars.some(p=>p[0]===i||p[1]===i);n.wealth=Math.max(0,Math.min(999,n.wealth+(fighting?-2:2)+random(s)*2));n.stability=Math.max(12,Math.min(100,n.stability+(fighting?-.6:.5)));n.population=Math.max(100,Math.round(n.population*(1+(fighting?-.003:.006))*(now[i]/counts[i])));if(n.stability<42&&random(s)<.015)rebel(s,i);});s.wars=s.wars.filter(p=>now[p[0]]&&now[p[1]]);s.alliances=s.alliances.filter(p=>now[p[0]]&&now[p[1]]);}
export function validate(s){if(!s||s.version!==1||!Number.isInteger(s.year)||s.year<1||!Number.isInteger(s.rng)||typeof s.seed!=='string'||!Array.isArray(s.nations)||s.nations.length<2||s.nations.length>24)throw Error('Invalid world save');if(!Array.isArray(s.owner)||s.owner.length!==W*H||!Array.isArray(s.terrain)||s.terrain.length!==W*H||!s.terrain.every(Number.isFinite)||!s.owner.every(n=>Number.isInteger(n)&&n>=-1&&n<s.nations.length))throw Error('Invalid map');s.nations.forEach((n,i)=>{if(n.id!==i||typeof n.name!=='string'||!/^#[0-9a-f]{6}$/i.test(n.color)||!Number.isInteger(n.capital)||n.capital<0||n.capital>=W*H||!['wealth','stability','population','aggression'].every(k=>Number.isFinite(n[k])&&n[k]>=0))throw Error('Invalid nation');});for(const key of ['wars','alliances'])if(!Array.isArray(s[key])||!s[key].every(p=>Array.isArray(p)&&p.length>1&&p.every(Number.isFinite)&&p[0]>=0&&p[1]<s.nations.length&&p[0]<p[1]))throw Error('Invalid diplomacy');if(!Array.isArray(s.events)||s.events.length>100||!s.events.every(e=>typeof e.text==='string'&&Number.isFinite(e.year)))throw Error('Invalid history');return s;}
